<script>
 import {Check,AlertCircle,Copy} from 'lucide-svelte';import {studio,notify} from '../studio.svelte';import {bytes,isTeam} from '../api';import {saveFileAs,descriptor} from '../local-downloads.js';let {report=[],attempted=0,cancelled=0}=$props();
 const status=s=>s==='ok'?"已导出":s==='EXPORT_TARGET_UNREACHABLE'?"未达到大小要求":s.split(':')[0].replaceAll('_',' ').toLowerCase();
</script>
{#if report}<div class="export-results"><h3>导出结果 · {report.filter(i=>i.status==='ok').length} / {attempted} 已导出</h3>{#if cancelled}<p class="hint">{cancelled} 张图片已取消，未开始处理。</p>{/if}{#each report as item}<div class="result-row">{#if item.path}<Check size={15}/>{:else}<AlertCircle size={15}/>{/if}<span>{item.name}<small>{item.path|| (item.status==='EXPORT_TARGET_UNREACHABLE'?"请提高文件大小上限、缩小尺寸，或改用 WebP。":item.status)}</small></span><b>{bytes(item.bytes)}</b><em>{status(item.status)}</em>{#if item.path&&isTeam}<a href={item.path} download={item.downloadName||item.name} onclick={e=>{e.preventDefault();saveFileAs(descriptor(item.path,item.downloadName||item.name)).catch(e=>studio.error=e.message);}}>另存为</a>{:else if item.path}<button aria-label={`Copy path for ${item.name}`} onclick={async()=>{try{await navigator.clipboard.writeText(item.path);notify("已复制路径");}catch{notify('复制失败，请选择路径后手动复制。',null,{state:'failed'});}}}><Copy size={14}/></button>{/if}</div>{/each}</div>{/if}
<style>.export-results{margin-top:12px}.export-results h3{font-size:12px;color:var(--text-dim)}.export-results .result-row{flex-wrap:wrap;gap:8px;padding:12px 0;border-color:var(--border)}.export-results .result-row>span{min-width:120px;max-width:100%;overflow-wrap:anywhere}.export-results .result-row small{overflow-wrap:anywhere;color:var(--text-dim)}.export-results .result-row em{color:var(--text-dim)}</style>
